import{schedule,effectiveTime}from'./study-core.mjs';
const $=s=>document.querySelector(s);const limit=180;let attempt=0,recordedAt,plan,pid,index=0,records=[],active=false,waiting=false,start=0,timer,trace=[],snapshot,datasetHash,device,skill,mode;
function current(){return plan.tasks[index];}
function next(){if(index>=plan.tasks.length){$('#task').hidden=true;$('#done').hidden=false;$('#frame').src='about:blank';return;}const t=current();$('#prompt').textContent=`課題 ${index+1}/6：${t.prompt}`;$('#answer').textContent=t.answer;$('#condition').textContent=`条件：${t.condition==='enhanced'?'カテゴリ画面':'一覧画面'} / 組${plan.group} / ${t.set}`;$('#answer-box').open=false;$('#start').disabled=false;$('#finish').hidden=true;$('#clock').textContent='開始前';$('#frame').src='about:blank';}
function exportData(){const payload={schemaVersion:1,dataKind:mode,datasetAsOf:snapshot.asOf,datasetSha256:datasetHash,recordedAt,limitSeconds:limit,participant:pid,group:plan.group,device,digitalSkill:skill,complete:records.length===6,records};const b=new Blob([JSON.stringify(payload,null,2)+'\n'],{type:'application/json'});const url=URL.createObjectURL(b);const a=document.createElement('a');a.href=url;a.download=`${mode}_${pid}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function finish(outcome){if(!active)return;const rawElapsed=(performance.now()-start)/1000;const elapsed=Math.min(rawElapsed,limit);if(rawElapsed>=limit)outcome='timeout';active=false;clearInterval(timer);records.push({taskId:current().id,condition:current().condition,period:current().period,set:current().set,outcome,elapsedSeconds:+elapsed.toFixed(3),effectiveSeconds:effectiveTime(outcome,elapsed,limit),actions:trace});$('#count').textContent=`記録済み：${records.length}課題。途中でもJSONを保存できます。`;index++;next();}
$('#setup').onsubmit=async ev=>{ev.preventDefault();try{pid=$('#pid').value.trim();plan=schedule(pid);if(!$('#consent').checked)throw Error('参加説明と同意を確認してください。');const r=await fetch('./data/information.json',{cache:'no-store'});if(!r.ok)throw Error('データを取得できません。');const bytes=await r.arrayBuffer();snapshot=JSON.parse(new TextDecoder().decode(bytes));datasetHash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join('');recordedAt=new Date().toISOString();device=$('#device').value;skill=$('#skill').value;mode=$('#mode').value;$('#setup').hidden=true;$('#task').hidden=false;$('#save').hidden=false;next();}catch(e){$('#setup-error').textContent=e.message;}};
$('#start').onclick=()=>{if(active||waiting)return;waiting=true;const requestId=++attempt;$('#start').disabled=true;$('#clock').textContent='画面の読み込み中';trace=[];$('#frame').src=`index.html?study=1${current().condition==='baseline'?'&view=baseline':''}`;setTimeout(()=>{if(waiting&&requestId===attempt){waiting=false;$('#start').disabled=false;$('#clock').textContent='読み込みに失敗しました。接続を確認して再試行してください。';}},10000);};
window.addEventListener('message',ev=>{if(ev.origin!==location.origin||ev.source!==$('#frame').contentWindow||ev.data?.type!=='nabari-action')return;if(waiting&&ev.data.action==='ready'){waiting=false;active=true;start=performance.now();$('#finish').hidden=false;timer=setInterval(()=>{const s=Math.min((performance.now()-start)/1000,limit);$('#clock').textContent=`${s.toFixed(1)} / ${limit} 秒`;if(s>=limit)finish('timeout');},100);return;}if(active&&['category','reset','search','detail','source'].includes(ev.data.action))trace.push({action:ev.data.action,id:String(ev.data.id||'').slice(0,60),atSeconds:+((performance.now()-start)/1000).toFixed(3)});});
document.querySelectorAll('[data-outcome]').forEach(b=>b.onclick=()=>finish(b.dataset.outcome));$('#save').onclick=exportData;
window.addEventListener('beforeunload',ev=>{if(records.length||active||waiting){ev.preventDefault();ev.returnValue='';}});
